declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('project_tasks.view');$pdo=db();$taskId=(int)($_GET['task_id']??0);$projectId=(int)($_GET['project_id']??0);$month=preg_match('/^\d{4}-\d{2}$/',(string)($_GET['month']??''))?(string)$_GET['month']:date('Y-m');function ics_e(string$v):string{return str_replace(["\\",";",",","\r","\n"],["\\\\","\\;","\\,",'',"\\n"],$v);} $where=[];$params=[];if($taskId){$where[]='t.id=?';$params[]=$taskId;}else{$where[]='t.due_date BETWEEN ? AND ?';$params[]=date('Y-m-01',strtotime($month.'-01'));$params[]=date('Y-m-t',strtotime($month.'-01'));if($projectId){$where[]='t.project_id=?';$params[]=$projectId;}}$s=$pdo->prepare("SELECT t.id,t.title,t.description,t.due_date,p.name project_name,c.company_name,u.name assigned_name FROM project_tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN clients c ON c.id=p.client_id LEFT JOIN users u ON u.id=t.assigned_to WHERE ".implode(' AND ',$where)." ORDER BY t.due_date,t.id");$s->execute($params);$rows=$s->fetchAll();header('Content-Type: text/calendar; charset=UTF-8');header('Content-Disposition: attachment; filename="socrates-project-calendar-'.date('Ymd-His').'.ics"');echo "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Socrates CRM//Project Calendar//ES\r\nCALSCALE:GREGORIAN\r\n";foreach($rows as$r){$start=date('Ymd',strtotime($r['due_date']));$end=date('Ymd',strtotime($r['due_date'].' +1 day'));$desc=trim('Proyecto: '.$r['project_name'].'\n'.($r['company_name']?'Cliente: '.$r['company_name'].'\n':'').($r['assigned_name']?'Responsable: '.$r['assigned_name'].'\n':'').($r['description']??''));echo "BEGIN:VEVENT\r\nUID:task-".(int)$r['id'].'@'.parse_url(app_url(),PHP_URL_HOST)."\r\nDTSTAMP:".gmdate('Ymd\THis\Z')."\r\nDTSTART;VALUE=DATE:$start\r\nDTEND;VALUE=DATE:$end\r\nSUMMARY:".ics_e($r['title'])."\r\nDESCRIPTION:".ics_e($desc)."\r\nURL:".ics_e(app_url('project_task_form.php?id='.(int)$r['id']))."\r\nEND:VEVENT\r\n";}echo "END:VCALENDAR\r\n";exit;
